set -e; D=$(mktemp -d); PG=/opt/homebrew/opt/postgresql@16/bin; [ -x $PG/initdb ] || PG=/opt/homebrew/bin
$PG/initdb -D $D/data -U postgres -A trust >/dev/null; $PG/pg_ctl -D $D/data -o "-p 54329 -k $D -c listen_addresses=''" -l $D/log start >/dev/null
P="$PG/psql -h $D -p 54329 -U postgres -v ON_ERROR_STOP=1 -q"
$P <<'SQL'
create role anon; create role authenticated; create role service_role;
create schema auth;
create table auth.users (id uuid primary key, email text, raw_user_meta_data jsonb);
create function auth.uid() returns uuid language sql stable as $$ select null::uuid $$;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on functions to service_role;
alter default privileges in schema public grant all on sequences to service_role;
revoke all on schema public from public; grant usage on schema public to anon, authenticated, service_role;
SQL
for f in supabase/migrations/*.sql; do echo "apply $f"; $P -1 -f $f; done
echo "$D" > /tmp/fresh_pg_dir; echo ok

